<?php
namespace App\Services; use App\Enums\{OrderStatus, PaymentStatus}; use App\Events\PaymentSucceeded; use App\Jobs\ReleaseReferralReward; use App\Models\{Order, Payment}; use Illuminate\Support\Facades\DB;
class PaymentService { public function createInvoice(Order $order, string $method = 'midtrans'): Payment { return $order->payments()->create(['payment_method'=>$method,'payment_gateway'=>'midtrans','amount'=>$order->total_price,'status'=>PaymentStatus::Pending]); } public function markPaid(Payment $payment, ?string $reference = null): Payment { return DB::transaction(function() use ($payment,$reference){ $payment->update(['status'=>PaymentStatus::Paid,'gateway_reference'=>$reference,'paid_at'=>now()]); $payment->order->update(['status'=>OrderStatus::Paid]); event(new PaymentSucceeded($payment)); ReleaseReferralReward::dispatch($payment->order); return $payment->refresh(); }); } public function handleMidtransWebhook(array $payload): ?Payment { $payment = Payment::where('gateway_reference', $payload['order_id'] ?? null)->first(); return $payment && in_array(($payload['transaction_status'] ?? ''), ['settlement','capture'], true) ? $this->markPaid($payment, $payload['transaction_id'] ?? null) : $payment; } }
